// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";

interface IGovernedAccessControl is IAccessControl, IERC165 {}

// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.30;

import {IGovernedAccessControl} from "./IGovernedAccessControl.sol";
import {IUSDxMarket} from "./IUSDxMarket.sol";

interface IPrimaryMarketConfig is IGovernedAccessControl {
    event AssetAdded(address indexed asset);
    event AssetRemoved(address indexed asset);
    event CustodianAdded(address indexed custodian);
    event CustodianRemoved(address indexed custodian);
    event MaxMintPerBlockChanged(uint256 oldMaxMintPerBlock, uint256 newMaxMintPerBlock);
    event MaxRedeemPerBlockChanged(uint256 oldMaxRedeemPerBlock, uint256 newMaxRedeemPerBlock);
    event WhitelistSet(address indexed account, bool allowed);
    event RouteSet(
        bytes32 indexed routeId,
        IUSDxMarket.OrderSide indexed side,
        address indexed inputAsset,
        address outputAsset,
        IUSDxMarket.SettlementMode mode,
        bool enabled
    );
    event ChannelSet(
        bytes32 indexed channelId,
        bytes32 indexed routeId,
        address indexed custodian,
        address destination,
        bool enabled,
        bytes32 channelHash
    );
    event ChannelStatusSet(bytes32 indexed channelId, bool enabled);
    event CapSet(
        bytes32 indexed capId,
        IUSDxMarket.CapScope indexed scope,
        bytes32 indexed subject,
        uint256 cap,
        IUSDxMarket.WindowType windowType,
        uint64 windowSize,
        bool enabled
    );
    event CapacityPaused(bytes32 indexed capId, IUSDxMarket.CapScope indexed scope, bytes32 indexed subject);
    event CapacityUnpaused(bytes32 indexed capId, IUSDxMarket.CapScope indexed scope, bytes32 indexed subject);
    event CapacityConsumed(
        bytes32 indexed consumptionId,
        bytes32 indexed routeId,
        bytes32 indexed accountId,
        bytes32 channelId,
        uint256 amount
    );
    event SignerAccountSet(address indexed signer, bytes32 indexed accountId);

    error InvalidAddress();
    error InvalidAssetAddress();
    error InvalidAmount();
    error InvalidRoute();
    error InvalidChannel();

    function SETTLEMENT_MANAGER_ROLE() external view returns (bytes32);
    function EMERGENCY_ROLE() external view returns (bytes32);

    function mintEnabled() external view returns (bool);
    function redeemEnabled() external view returns (bool);
    /// @notice Global mint capacity keyed by `block.number`.
    /// @dev The wall-clock meaning of one block is chain-dependent; recalibrate per deployment chain.
    function maxMintPerBlock() external view returns (uint256);
    /// @notice Global redeem capacity keyed by `block.number`.
    /// @dev The wall-clock meaning of one block is chain-dependent; recalibrate per deployment chain.
    function maxRedeemPerBlock() external view returns (uint256);
    function mintedPerBlock(uint256 blockNumber) external view returns (uint256);
    function redeemedPerBlock(uint256 blockNumber) external view returns (uint256);

    function route(bytes32 routeId) external view returns (IUSDxMarket.RouteState memory);
    function channel(bytes32 channelId) external view returns (IUSDxMarket.ChannelState memory);
    function isRouteEnabled(bytes32 routeId) external view returns (bool);
    function isChannelEnabled(bytes32 channelId) external view returns (bool);
    function isSupportedAsset(address asset) external view returns (bool);
    function getCurrentBlockCapacity() external view returns (IUSDxMarket.BlockCapacity memory);
    /// @notice Legacy compatibility view; no address-scoped block limit is configured through this selector.
    /// @dev Per-account throttling is enforced through ACCOUNT-scope caps keyed by order.accountId.
    function getUserLimit(address account) external view returns (IUSDxMarket.UserLimit memory);
    /// @notice Legacy compatibility view; does not report protocol-wide capacity as address-scoped capacity.
    /// @dev Use getCurrentBlockCapacity for global block capacity and ACCOUNT-scope capUsage for account limits.
    function getUserBlockCapacity(address account) external view returns (IUSDxMarket.UserBlockCapacity memory);
    function getSupportedAssets() external view returns (address[] memory);
    function getCustodians() external view returns (address[] memory);
    function isCustodian(address account) external view returns (bool);
    function isWhitelisted(address account) external view returns (bool);
    function signerAccount(address signer) external view returns (bytes32);
    function checkChannel(IUSDxMarket.ChannelCheck calldata channelCheck)
        external
        view
        returns (IUSDxMarket.ChannelDecision memory);
    function cap(IUSDxMarket.CapKey calldata key) external view returns (IUSDxMarket.CapConfig memory);
    function capUsage(IUSDxMarket.CapKey calldata key) external view returns (IUSDxMarket.CapUsage memory);
    function checkCapacity(IUSDxMarket.CapacityRequest calldata request)
        external
        view
        returns (IUSDxMarket.CapacityCheck memory);
    function maxCapacity(IUSDxMarket.CapacityRequest calldata request) external view returns (uint256);

    function consumeCapacity(IUSDxMarket.CapacityRequest calldata request) external returns (bytes32 consumptionId);
    function consumeBlockCapacity(IUSDxMarket.OrderSide side, uint256 amount) external;
    function setCap(IUSDxMarket.CapKey calldata key, IUSDxMarket.CapConfig calldata config) external;
    function pauseCapacity(IUSDxMarket.CapKey calldata key) external;
    function unpauseCapacity(IUSDxMarket.CapKey calldata key) external;
    function setRoute(IUSDxMarket.RouteState calldata routeState) external;
    function setChannel(IUSDxMarket.ChannelState calldata channelState) external;
    function setChannelStatus(bytes32 channelId, bool enabled) external;
    function setWhitelist(address account, bool allowed) external;
    function setSignerAccount(address signer, bytes32 accountId) external;
    function setMintRedeemEnabled(bool mintEnabled_, bool redeemEnabled_) external;
    function setMaxMintPerBlock(uint256 newMaxMintPerBlock) external;
    function setMaxRedeemPerBlock(uint256 newMaxRedeemPerBlock) external;
}

