pragma solidity 0.8.30;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import {IGovernedAccessControl} from "./IGovernedAccessControl.sol";

interface IUSDx is IERC20, IERC20Metadata, IERC20Permit, IGovernedAccessControl {
    event Paused(address account);
    event Unpaused(address account);
    event Blacklisted(address indexed account);
    event UnBlacklisted(address indexed account);
    event BridgeMint(address indexed bridge, address indexed to, uint256 amount);
    event BridgeBurn(address indexed bridge, address indexed from, uint256 amount);

    error RestrictedAddress(address account);
    error ZeroAddress();

    function MARKET_ROLE() external view returns (bytes32);

    function BRIDGE_ROLE() external view returns (bytes32);

    function RESTRICTION_ROLE() external view returns (bytes32);

    function PAUSER_ROLE() external view returns (bytes32);

    function paused() external view returns (bool);

    /// @notice Blacklisted accounts are blocked as transfer parties and as allowance spenders.
    function isBlacklisted(address account) external view returns (bool);

    function blacklist(address account) external;

    function unBlacklist(address account) external;

    function pause() external;

    function unpause() external;

    function mint(address to, uint256 amount) external;

    function burn(uint256 amount) external;

    function burnFrom(address from, uint256 amount) external;

    function bridgeMint(address to, uint256 amount) external;

    function bridgeBurn(uint256 amount) external;
}

// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.30;

import {IGovernedAccessControl} from "./IGovernedAccessControl.sol";

interface IUSDxMarket is IGovernedAccessControl {
    enum OrderSide {
        MINT,
        REDEEM
    }

    enum SignatureType {
        EIP712
    }

    enum SignerStatus {
        REJECTED,
        PENDING,
        ACCEPTED
    }

    enum SettlementMode {
        CUSTODY,
        ADAPTER,
        CROSS_CHAIN
    }

    enum CapScope {
        GLOBAL,
        ASSET,
        ROUTE,
        ACCOUNT,
        CHANNEL
    }

    /// @notice Capacity window basis.
    /// @dev `BLOCK` windows are keyed by `block.number`, whose wall-clock cadence is chain-dependent.
    /// Use `FIXED` timestamp buckets when a wall-clock throttle is intended.
    enum WindowType {
        NONE,
        BLOCK,
        FIXED
    }

    struct Signature {
        SignatureType signatureType;
        bytes signatureBytes;
    }

    struct Order {
        bytes32 accountId;
        bytes32 routeId;
        bytes32 channelId;
        address signer;
        OrderSide side;
        address inputAsset;
        address outputAsset;
        uint256 inputAmount;
        uint256 minOutputAmount;
        address receiver;
        uint256 deadline;
        uint256 nonce;
        bytes32 termsHash;
    }

    struct RouteState {
        bytes32 routeId;
        OrderSide side;
        address inputAsset;
        address outputAsset;
        SettlementMode mode;
        bool enabled;
        uint256 minInputAmount;
        uint256 minOutputAmount;
    }

    struct ChannelState {
        bytes32 channelId;
        bytes32 routeId;
        address custodian;
        address adapter;
        address destination;
        bytes32 destinationDomain;
        bool enabled;
        bytes32 channelHash;
    }

    struct ChannelCheck {
        bytes32 accountId;
        bytes32 channelId;
        OrderSide side;
        address inputAsset;
        address outputAsset;
        address receiver;
        uint256 amount;
    }

    struct ChannelDecision {
        bool allowed;
        bytes32 reasonCode;
        bytes32 routeId;
        address custodian;
        address destination;
    }

    struct CapKey {
        CapScope scope;
        bytes32 subject;
        bytes32 routeId;
        bytes32 channelId;
        address asset;
    }

    struct CapConfig {
        // Maximum capacity in USDx wei notional unless a future field explicitly names another basis.
        // Mint capacity uses USDx output (`minOutputAmount`); redeem capacity uses USDx input (`inputAmount`).
        uint256 cap;
        // `BLOCK` windows reset when `block.number` changes; `FIXED` windows reset on timestamp buckets.
        WindowType windowType;
        uint64 windowSize;
        bool enabled;
    }

    struct CapUsage {
        uint256 used;
        uint256 available;
        uint256 windowStart;
        uint256 windowEnd;
        uint256 resetsAt;
    }

    struct CapacityRequest {
        bytes32 routeId;
        bytes32 accountId;
        bytes32 channelId;
        OrderSide side;
        address inputAsset;
        address outputAsset;
        uint256 inputAmount;
        uint256 minOutputAmount;
    }

    struct CapacityCheck {
        bool allowed;
        bytes32 reasonCode;
        // Effective remaining capacity in the same USDx-notional basis as `requiredAmount`.
        uint256 effectiveAvailable;
        // Required USDx wei notional: mint output, redeem input.
        uint256 requiredAmount;
    }

    struct SettlementCheck {
        bool allowed;
        bytes32 reasonCode;
        bytes32 orderHash;
        bytes32 routeId;
        bytes32 channelId;
        // Remaining USDx wei notional capacity after applying all configured caps.
        uint256 availableNotionalAmount;
        // Required USDx wei notional for this order: mint output, redeem input.
        uint256 requiredNotionalAmount;
    }

    struct Movement {
        address inputAsset;
        address outputAsset;
        address source;
        address destination;
        address receiver;
        uint256 inputAmount;
        uint256 outputAmount;
    }

    struct SupplyChange {
        int256 usdxDelta;
        address account;
        address receiver;
    }

    /// @notice Canonical settlement receipt shape, reconstructed off-chain from the
    /// signed order, `OrderSettled` event, and the supply delta derived from `side`
    /// and the settled amounts. No on-chain getter returns this struct; it is the
    /// schema indexers and auditors rebuild.
    struct PrimaryMarketProof {
        bytes32 proofId;
        bytes32 orderHash;
        bytes32 accountId;
        bytes32 routeId;
        bytes32 channelId;
        OrderSide side;
        Movement movement;
        SupplyChange supplyChange;
        bytes32 settlementHash;
    }

    struct MintingState {
        address usdx;
        uint256 chainId;
        bytes32 domainSeparator;
        uint256 maxMintPerBlock;
        uint256 maxRedeemPerBlock;
        uint256 mintedThisBlock;
        uint256 redeemedThisBlock;
        bool mintEnabled;
        bool redeemEnabled;
    }

    struct BlockCapacity {
        uint256 blockNumber;
        uint256 mintUsed;
        uint256 mintAvailable;
        uint256 redeemUsed;
        uint256 redeemAvailable;
    }

    struct UserLimit {
        uint256 maxMintPerBlock;
        uint256 maxRedeemPerBlock;
        bool custom;
    }

    struct UserBlockCapacity {
        address account;
        uint256 blockNumber;
        uint256 mintUsed;
        uint256 mintAvailable;
        uint256 redeemUsed;
        uint256 redeemAvailable;
    }

    struct OrderCheck {
        bool valid;
        bytes32 code;
        bytes32 orderHash;
        address signer;
        bool nonceUsed;
        uint256 availableBlockCapacity;
    }

    event Mint(
        address indexed caller,
        address indexed sender,
        address indexed receiver,
        address collateralAsset,
        uint256 collateralAmount,
        uint256 usdxAmount
    );
    event Redeem(
        address indexed caller,
        address indexed sender,
        address indexed receiver,
        address collateralAsset,
        uint256 collateralAmount,
        uint256 usdxAmount
    );
    event OrderSettled(
        bytes32 indexed proofId,
        bytes32 indexed orderHash,
        bytes32 indexed accountId,
        bytes32 routeId,
        bytes32 channelId,
        address destination,
        bytes32 channelHash,
        bytes32 settlementHash
    );
    event OrderCancelled(bytes32 indexed orderHash, bytes32 indexed accountId);
    event DelegatedSignerInitiated(address indexed signer, address indexed source);
    event DelegatedSignerAdded(address indexed signer, address indexed source);
    event DelegatedSignerRemoved(address indexed signer, address indexed source);

    error InvalidAddress();
    error InvalidUSDxAddress();
    error InvalidAssetAddress();
    error InvalidCustodianAddress();
    error InvalidOrder();
    error InvalidAmount();
    error InvalidRoute();
    error InvalidChannel();
    error UnsupportedAsset();
    error NoAssetsProvided();
    error InvalidSignature();
    error InvalidNonce();
    error SignatureExpired();
    error TransferFailed();
    error MaxMintPerBlockExceeded();
    error MaxRedeemPerBlockExceeded();
    error CapacityExceeded(bytes32 reasonCode);
    error UserMintLimitExceeded();
    error UserRedeemLimitExceeded();
    error NotWhitelisted();
    error SignerNotInitiated();
    error InsufficientBalance();

    function MINT_OPERATOR_ROLE() external view returns (bytes32);
    function REDEEM_OPERATOR_ROLE() external view returns (bytes32);
    function SETTLEMENT_MANAGER_ROLE() external view returns (bytes32);

    function DOMAIN_SEPARATOR() external view returns (bytes32);
    function eip712Domain()
        external
        view
        returns (
            bytes1 fields,
            string memory name,
            string memory version,
            uint256 chainId,
            address verifyingContract,
            bytes32 salt,
            uint256[] memory extensions
        );
    function ORDER_TYPEHASH() external view returns (bytes32);
    function hashOrder(Order calldata order) external view returns (bytes32);
    function orderState(bytes32 orderHash) external view returns (bool settled, bool cancelled, bytes32 proofId);
    function verifyOrder(Order calldata order, Signature calldata signature) external view returns (bytes32);
    function verifyNonce(bytes32 accountId, uint256 nonce) external view returns (uint256, uint256, uint256);
    function route(bytes32 routeId) external view returns (RouteState memory);
    function channel(bytes32 channelId) external view returns (ChannelState memory);
    function isRouteEnabled(bytes32 routeId) external view returns (bool);
    function isChannelEnabled(bytes32 channelId) external view returns (bool);
    function isSupportedAsset(address asset) external view returns (bool);
    function getMintingState() external view returns (MintingState memory);
    function getCurrentBlockCapacity() external view returns (BlockCapacity memory);
    /// @notice Legacy compatibility view; no address-scoped block limit is configured through this selector.
    /// @dev Per-account throttling is enforced through ACCOUNT-scope caps keyed by order.accountId.
    function getUserLimit(address account) external view returns (UserLimit memory);
    /// @notice Legacy compatibility view; does not report protocol-wide capacity as address-scoped capacity.
    /// @dev Use getCurrentBlockCapacity for global block capacity and ACCOUNT-scope capUsage for account limits.
    function getUserBlockCapacity(address account) external view returns (UserBlockCapacity memory);
    function getSupportedAssets() external view returns (address[] memory);
    function getCustodians() external view returns (address[] memory);
    function isCustodian(address account) external view returns (bool);
    function isWhitelisted(address account) external view returns (bool);
    function signerAccount(address signer) external view returns (bytes32);
    function delegatedSigner(address signer, address source) external view returns (SignerStatus);
    function isNonceUsed(bytes32 accountId, uint256 nonce) external view returns (bool);
    function checkChannel(ChannelCheck calldata channelCheck) external view returns (ChannelDecision memory);
    function cap(CapKey calldata key) external view returns (CapConfig memory);
    function capUsage(CapKey calldata key) external view returns (CapUsage memory);
    function checkCapacity(CapacityRequest calldata request) external view returns (CapacityCheck memory);
    function maxCapacity(CapacityRequest calldata request) external view returns (uint256);
    /// @notice Previews whether an order can settle under current policy, routing, nonce, signature, and capacity state.
    /// @dev `settlementData` is intentionally ignored by this preview. It only contributes to the `settlementHash`
    /// emitted in `OrderSettled` during actual settlement.
    function checkSettlement(Order calldata order, Signature calldata signature, bytes calldata settlementData)
        external
        view
        returns (SettlementCheck memory);
    function settle(Order calldata order, Signature calldata signature, bytes calldata settlementData)
        external
        returns (bytes32 proofId);
    function proofOfOrder(bytes32 orderHash) external view returns (bytes32 proofId);
    function checkMint(Order calldata order, Signature calldata signature) external view returns (OrderCheck memory);
    function checkRedeem(Order calldata order, Signature calldata signature) external view returns (OrderCheck memory);
    /// @notice Tombstones an order hash so it can never settle.
    /// @dev Signature verification is intentionally not part of cancellation. Orders are off-chain artifacts, and an
    /// authorized settlement manager may preemptively cancel a hash even if the order was never submitted on-chain.
    /// Cancellation does not consume the order nonce.
    function cancelOrder(Order calldata order) external;
    function setDelegatedSigner(address signer) external;
    function confirmDelegatedSigner(address source) external;
    function removeDelegatedSigner(address signer) external;
    function mint(Order calldata order, Signature calldata signature, bytes calldata settlementData) external;
    function redeem(Order calldata order, Signature calldata signature, bytes calldata settlementData) external;
}
